    public void setWheelRotations(float fl, float fr, float rl, float rr) {
        this.FRWheelPivot.xRot = Trig.toRadians(fr);
        this.FLWheelPivot.xRot = Trig.toRadians(fl);
        this.RRWheelPivot.xRot = Trig.toRadians(rr);
        this.RLWheelPivot.xRot = Trig.toRadians(rl);
    }

    public void setTurretRotation(float yaw) {
        this.turretMidBeam.yRot = Trig.toRadians(yaw);
    }

    public void setArmRotation(float pitch) {
        this.armMain.xRot = Trig.toRadians(pitch);
    }

    public void setCrankRotations(float angle) {
        this.pulleyAxle.xRot = Trig.toRadians(angle);
    }
